window.CURRENT_LANG=window.__ccDefaultLang||'nl';var TRANSLATIONS={en:{'nav.hamburger.open':'Open menu','nav.hamburger.close':'Close menu','cta.success':'Sent!','cta.btn':'Get Free Roadmap'},nl:{'nav.hamburger.open':'Menu openen','nav.hamburger.close':'Menu sluiten','cta.success':'Verstuurd!','cta.btn':'Ontvang gratis stappenplan'}};function ccOtherLangUrl(){var p=location.pathname,e=p==='/en'||p.indexOf('/en/')===0,t=e?(p.replace(/^\/en/,'')||'/'):('/en'+p);return t+location.search+location.hash;}document.addEventListener('DOMContentLoaded',function(){var t=document.getElementById('langToggle');if(t)t.addEventListener('click',function(){location.href=ccOtherLangUrl();});});
